import sys

def count_colors(arr, start, end):
    visited = [False] * 24
    count = 0
    for i in range(start, end + 1):
        color = arr[i]
        if not visited[color]:
            visited[color] = True
            count += 1
    return count

def main():
    input_line = sys.stdin.readline().strip()
    a, b, l, r = map(int, input_line.split())
    l -= 1
    r -= 1
    total = a + b
    repeats = 4
    pattern = [0] * (total * repeats)
    shiftH = l // total
    l -= shiftH * total
    r -= shiftH * total
    segmentCount = (r - l + 1) // total
    if segmentCount > 2:
        r -= (segmentCount - 2) * total
    diff = max(a - b, 1)
    for rep in range(repeats):
        for k in range(a - diff):
            pattern[total * rep + k] = k
        for k in range(diff):
            pattern[total * rep + a - diff + k] = (a - diff + k) if rep % 2 == 0 else a + k
    minColorsCount = a + a
    for shiftAIdx in range(1, diff + 1):
        for k in range(b):
            pattern[a + k] = pattern[a - shiftAIdx]
        for shiftBIdx1 in range(1, diff + 1):
            for k in range(b):
                pattern[total + a + k] = pattern[total + a - shiftBIdx1]
            for shiftBIdx2 in range(1, diff + 1):
                for k in range(b):
                    pattern[2 * total + a + k] = pattern[2 * total + a - shiftBIdx2]
                for shiftBIdx3 in range(1, diff + 1):
                    for k in range(b):
                        pattern[3 * total + a + k] = pattern[3 * total + a - shiftBIdx3]
                    minColorsCount = min(minColorsCount, count_colors(pattern, l, r))
    print(minColorsCount)

if __name__ == "__main__":
    main()

